#include <iostream>

// Khai bao nguyen mau cho de quy gian tiep (mutual recursion)
bool isOdd(int n);

bool isEven(int n) {
    if (n == 0) return true;   // Base case
    return isOdd(n - 1);       // Recursive call to isOdd
}

bool isOdd(int n) {
    if (n == 0) return false;  // Base case
    return isEven(n - 1);      // Recursive call to isEven
}

// Minh hoa thu tu thuc thi truoc va sau loi goi de quy
void traceUnwind(int n) {
    if (n <= 0) return;
    std::cout << "Down: " << n << "\n";
    traceUnwind(n - 1);
    std::cout << "Up: " << n << "\n";
}

int main() {
    int val = 4;
    std::cout << "Even check for " << val << ": " << (isEven(val) ? "true" : "false") << "\n";
    traceUnwind(3);
    return 0;
}

#include <iostream>

// Bien toan cuc dem tong so lan ham duoc kich hoat
static long long callCount = 0;

int fib(int index) {
    ++callCount;
    if (index == 0) return 0;
    if (index == 1) return 1;
    return fib(index - 1) + fib(index - 2);
}

// Phuong phap lap toi uu tuyen tinh O(n) va O(1) bo nho
int fibIterative(int index) {
    if (index == 0) return 0;
    if (index == 1) return 1;
    int f0 = 0, f1 = 1, f = 0;
    for (int i = 2; i <= index; ++i) {
        f = f0 + f1;
        f0 = f1;
        f1 = f;
    }
    return f;
}

int main() {
    int n = 7;
    callCount = 0;
    int recResult = fib(n);
    long long callsFor7 = callCount;
    int iterResult = fibIterative(n);

    std::cout << "fib(" << n << ") = " << recResult << "\n";
    std::cout << "Recursive calls count: " << callsFor7 << "\n";
    std::cout << "Iterative verification: " << iterResult << "\n";
    return 0;
}
